    "train_mask_dir = \"/mnt/e/平时作业/机器学习/大作业/眼底图像的渗出液分割/EX数据/groudtruth/训练\"\n",
    "test_image_dir = \"/mnt/e/平时作业/机器学习/大作业/眼底图像的渗出液分割/EX数据/去光照/测试\"\n",
    "test_mask_dir = \"/mnt/e/平时作业/机器学习/大作业/眼底图像的渗出液分割/EX数据/groudtruth/测试\"\n",
    "# 加载并划分训练/验证集\n",
    "X_train, y_train = load_dataset(train_image_dir, train_mask_dir)\n",
